img2 = struct.pack('>I', 0)
def png_data(w, h, px):
    raw = b''.join(b'\x00' + bytes(sum(([r, g, b, a] for (r, g, b, a) in px[y*w:(y+1)*w]), [])) for y in range(h))
    def ch(t, d):
        c = struct.pack('>I', len(d)) + t + d
        return c + struct.pack('>I', zlib.crc32(t + d) & 0xffffffff)
    return b'\x89PNG\r\n\x1a\n' + ch(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 6, 0, 0, 0)) + ch(b'IDAT', zlib.compress(raw)) + ch(b'IEND', b'')
